// Browser-side interaction checks against the real modules in the disposable
// i18n Electron host. No accounts, inference, plugins, or real workspace files.
export async function checkLocalizedModules({ core, i18n, check }) {
  const byId = id => document.getElementById(id);
  const change = (id, value) => {
    const input = byId(id);
    input.value = value;
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    return input;
  };
  const showTool = id => document.querySelector(`[data-tool-view="tool-${id}-view"]`).click();
  const numericText = id => byId(id).textContent.match(/-?\d+(?:\.\d+)?/g)?.join('|') || '';
  const settle = () => new Promise(resolve => setTimeout(resolve, 30));
  const { messageSpan } = await import('../../../src/renderer/lib/i18n/markup.js');
  const guarded = document.createElement('div');
  guarded.innerHTML = messageSpan('workflow.block.title', { index: 2, title: '\"><img src=x onerror=alert(1)>' })
    + '<span data-i18n="workflow.block.title" data-i18n-params="broken">Keep malformed parameters</span>'
    + '<span data-i18n="workflow.block.title" data-i18n-params=\'{"title":{}}\'>Keep nested parameters</span>';
  document.body.append(guarded);
  i18n.setLocale('en'); i18n.setLocale('es');
  check(!guarded.querySelector('img') && guarded.firstElementChild.textContent.startsWith('Bloque 2:'), 'Interpolated HTML remains literal text through language changes');
  check(guarded.children[1].textContent === 'Keep malformed parameters' && guarded.children[2].textContent === 'Keep nested parameters', 'Malformed or non-scalar DOM parameters preserve existing content');
  guarded.remove();
  core.navigationShell.showView('tool-box-view');
  i18n.setLocale('en');
  showTool('molarity');
  change('molarity-volume', '100');

  change('molarity-concentration', '10');
  change('molarity-mw', '58.44');
  const mass = byId('molarity-solver-result').textContent;
  const massValues = numericText('molarity-solver-result');
  check(mass.startsWith('Mass:') && mass.includes('58.44') && mass.endsWith('mg'), 'Molarity still computes the expected mass');
  i18n.setLocale('es-MX');
  check(byId('molarity-solver-result').textContent.startsWith('Masa:'), 'Computed molarity text translates live');
  check(byId('molarity-solver-result').getAttribute('data-caption') === 'Resultado:', 'CSS-generated result captions translate with their result text');
  check(numericText('molarity-solver-result') === massValues && byId('molarity-volume').value === '100', 'Molarity values and units survive translation');
  change('molarity-volume', '0');
  check(byId('molarity-solver-result').dataset.state === 'warning' && byId('molarity-solver-result').textContent.includes('números positivos'), 'Molarity validation translates on new input');
  change('molarity-volume', '100');

  change('dilution-stock-conc', '100'); change('dilution-target-conc', '10'); change('dilution-target-volume', '1');
  const dilutionNumbers = numericText('dilution-calc-result');
  check(byId('dilution-calc-result').textContent.startsWith('Usa '), 'Dilution instructions are Spanish');
  i18n.setLocale('en');
  check(byId('dilution-calc-result').textContent.startsWith('Use ') && numericText('dilution-calc-result') === dilutionNumbers, 'Dilution instruction translation preserves quantities and units');
  i18n.setLocale('es'); change('dilution-target-conc', '200');
  check(byId('dilution-calc-result').dataset.state === 'warning' && byId('dilution-calc-result').textContent.startsWith('La concentración'), 'Dilution warnings translate on input');
  change('dilution-stock-conc', ''); i18n.setLocale('en'); i18n.setLocale('es');
  check(byId('dilution-calc-result').textContent === '', 'Clearing an input removes a stale translated dilution warning');
  change('dilution-stock-conc', '100'); change('dilution-target-conc', '10');

  showTool('peptide');
  i18n.setLocale('en');
  const peptide = change('peptide-sequence', 'ACDEFWYCC');
  const peptideNumbers = numericText('peptide-result');
  const resultRow = byId('peptide-result').firstElementChild;
  peptide.focus(); peptide.setSelectionRange(2, 6);
  i18n.setLocale('es');
  check(byId('peptide-result').textContent.includes('Peso molecular:'), 'Peptide result labels translate');
  check(numericText('peptide-result') === peptideNumbers, 'Peptide scientific results remain identical');
  check(document.activeElement === peptide && peptide.selectionStart === 2 && peptide.selectionEnd === 6 && peptide.value === 'ACDEFWYCC', 'Calculator input focus, selection, and sequence are preserved');
  check(byId('peptide-result').firstElementChild === resultRow, 'Locale changes do not rebuild calculator result rows');
  change('peptide-sequence', 'WYCC');
  check(byId('peptide-result').textContent.includes('Longitud:') && byId('peptide-result').textContent.includes('4 aa'), 'New peptide calculations use Spanish labels');

  showTool('oligo'); i18n.setLocale('en');
  change('oligo-sequence', 'ACGTACGT');
  const oligoNumbers = numericText('oligo-result');
  i18n.setLocale('es');
  check(byId('oligo-result').textContent.includes('Contenido GC:') && numericText('oligo-result') === oligoNumbers, 'Oligo results translate without changing GC, Tm, mass, or extinction');
  check(byId('oligo-type').value === 'DNA' && byId('oligo-type').selectedOptions[0].textContent === 'ADN', 'Scientific option IDs remain stable while their labels translate');

  showTool('extinction'); i18n.setLocale('en');
  change('extinction-type', 'protein'); change('extinction-sequence', 'WYCC');
  const extinctionNumbers = numericText('extinction-result');
  i18n.setLocale('es');
  check(byId('extinction-result').textContent.includes('Extinción reducida') && numericText('extinction-result') === extinctionNumbers, 'Extinction labels translate without changing numerical coefficients');

  showTool('dna-protein');
  change('dna-protein-sequence', 'ATGAAATAA');
  const protein = byId('dna-protein-result').textContent;
  i18n.setLocale('en'); i18n.setLocale('es');
  check(protein === 'MK*' && byId('dna-protein-result').textContent === protein && byId('dna-protein-frame').value === '1', 'DNA translation and reading-frame IDs are unchanged');
  showTool('reverse-translate');
  change('reverse-translate-protein', 'MKT');
  const dna = byId('reverse-translate-result').textContent;
  const enzyme = byId('reverse-translate-site-available').querySelector('[data-site-name="EcoRI"]');
  enzyme.click();
  const selectedEnzyme = byId('reverse-translate-site-selected').firstElementChild;
  i18n.setLocale('en'); i18n.setLocale('es');
  check(byId('reverse-translate-result').textContent === dna && /^[ACGT]+$/.test(dna), 'Reverse translation preserves generated DNA');
  check(byId('reverse-translate-site-selected').firstElementChild === selectedEnzyme, 'Selected restriction enzymes are not rebuilt on locale changes');
  change('reverse-translate-site-filter', 'NO_SUCH_ENZYME');
  check(byId('reverse-translate-site-available').textContent.includes('Ninguna enzima'), 'Dynamic enzyme search empty states translate');

  showTool('buffer');
  change('buffer-name-1', 'NaCl'); change('buffer-final-1', '10 mM');
  const amount = byId('buffer-amount-1').placeholder;
  const mw = byId('buffer-mw-1').value;
  change('buffer-stock-1', '100 mM');
  check(byId('buffer-amount-1').placeholder.includes('solución madre'), 'Buffer stock quantities translate');
  check(byId('buffer-amount-1').getAttribute('aria-label') === 'Masa o volumen del ingrediente 1', 'Placeholder parameters retain the row accessibility index');
  change('buffer-stock-1', '1 mg/mL');
  check(byId('buffer-amount-1').placeholder.includes('no son compatibles'), 'Buffer concentration-unit warnings translate');
  i18n.setLocale('en');
  check(byId('buffer-amount-1').placeholder === 'stock and final concentration units are not compatible', 'Buffer warnings retain their original English wording');
  i18n.setLocale('es'); change('buffer-stock-1', '1 mM');
  check(byId('buffer-amount-1').placeholder.startsWith('la concentración final'), 'Buffer concentration-range warnings translate');
  change('buffer-amount-1', '2 g'); i18n.setLocale('en'); i18n.setLocale('es');
  check(byId('buffer-amount-1').value === '2 g', 'Manual quantities survive translated diagnostics');
  change('buffer-amount-1', ''); change('buffer-stock-1', '');
  for (let n = 0; n < 6; n++) byId('add-buffer-chemical-btn').click();
  check(byId('buffer-name-7').getAttribute('aria-label') === 'Sustancia química del ingrediente 7', 'Cloned buffer rows use the new row index in Spanish accessibility labels');
  i18n.setLocale('en');
  check(byId('buffer-name-7').getAttribute('aria-label') === 'Ingredient 7 chemical', 'Cloned row parameters survive a second language change');
  check(byId('buffer-amount-1').placeholder === amount && byId('buffer-mw-1').value === mw, 'Calculated buffer amounts are not overwritten by automatic placeholder translations');
  i18n.setLocale('es');
  byId('buffer-row-7').querySelector('[data-buffer-row-remove]').click();
  check(byId('buffer-row-7').hidden && byId('buffer-name-1').value === 'NaCl', 'Translated buffer rows still remove independently');

  showTool('fixed-reaction');
  change('fixed-reaction-name-1', 'My reagent'); change('fixed-reaction-stock-1', '100 mM'); change('fixed-reaction-final-1', '10 mM');
  const reactionVolume = byId('fixed-reaction-volume-1').placeholder;
  const solvent = byId('fixed-reaction-solvent-output').textContent;
  change('fixed-reaction-stock-1', '1 mg/mL');
  check(byId('fixed-reaction-volume-1').placeholder.includes('unidades compatibles'), 'Reaction unit warnings translate');
  change('fixed-reaction-stock-1', '1 mM');
  check(byId('fixed-reaction-volume-1').placeholder.startsWith('la concentración final'), 'Reaction concentration-range warnings translate');
  change('fixed-reaction-stock-1', '100 mM');
  check(!byId('fixed-reaction-volume-1').hasAttribute('data-i18n-placeholder') && byId('fixed-reaction-volume-1').placeholder === reactionVolume, 'A valid calculation replaces the translated warning without leaving a stale binding');
  for (let n = 0; n < 6; n++) byId('fixed-reaction-add-row-btn').click();
  check(byId('fixed-reaction-name-7').getAttribute('aria-label') === 'Reactivo de reacción 7', 'Cloned reaction rows have correct Spanish labels');
  i18n.setLocale('en'); i18n.setLocale('es');
  check(byId('fixed-reaction-volume-1').placeholder === reactionVolume && byId('fixed-reaction-solvent-output').textContent === solvent, 'Reaction and solvent volumes survive locale changes');

  core.navigationShell.showView('workflow-management-view');
  const workflows = core.moduleRuntime.modules.workflowManagement;
  workflows.openProcessDialog();
  check(byId('workflow-process-status').textContent.includes('Crea primero'), 'Workflow process empty-state guidance is Spanish');
  byId('workflow-process-form').dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
  check(byId('workflow-process-status').textContent.includes('al menos un paso'), 'Process validation uses translated text');
  byId('workflow-process-cancel').click();
  byId('workflow-entry-template-btn').click();
  const type = document.querySelector('input[name="workflow-block-type-option"][value="text"]');
  type.checked = true; type.dispatchEvent(new Event('change', { bubbles: true }));
  check(byId('workflow-block-add-btn').textContent === 'Añadir bloque de texto', 'Workflow composer action follows the selected block type in Spanish');
  change('workflow-block-text', 'Keep my typed step <&>');
  byId('workflow-block-add-btn').click();
  const node = byId('workflow-graph-nodes').firstElementChild;
  check(node?.textContent.includes('Bloque de texto'), 'New graph node UI labels translate');
  check(node.querySelector('[data-workflow-block-remove]').getAttribute('aria-label') === 'Eliminar bloque de texto', 'Graph node accessibility labels translate completely');
  check(byId('workflow-save-template-btn').getAttribute('data-hover-caption') === 'Guardar el grafo actual', 'Workflow hover captions use the active language');
  change('workflow-template-name', 'My template <&>');
  const description = change('workflow-template-description', 'Untouched scientific notes');
  description.focus(); description.setSelectionRange(2, 7);
  i18n.setLocale('en');
  check(byId('workflow-template-name').value === 'My template <&>' && description.value === 'Untouched scientific notes', 'Locale changes preserve workflow template drafts');
  check(document.activeElement === description && description.selectionStart === 2 && description.selectionEnd === 7, 'Workflow text selection remains active');
  check(byId('workflow-graph-nodes').firstElementChild === node && node.textContent.includes('Text Block'), 'Workflow nodes retain identity and geometry while labels change');
  check(byId('workflow-block-add-btn').textContent === 'Add Text Block', 'A locale change does not reset the workflow composer mode');
  node.dispatchEvent(new MouseEvent('contextmenu', { bubbles: true, clientX: 650, clientY: 280 }));
  const menuButton = byId('workflow-graph-context-menu').querySelector('[data-workflow-menu-action="delete-selected"]');
  i18n.setLocale('es');
  check(menuButton.textContent === 'Eliminar bloque' && menuButton.isConnected, 'An open workflow context menu translates without replacing its handlers');
  byId('workflow-graph-context-menu').querySelector('[data-workflow-menu-action="clear-selection"]').click();
  byId('workflow-save-template-btn').click();
  check(core.state.workflowTemplates.length === 1 && core.state.workflowTemplates[0].name === 'My template <&>', 'Saving a Spanish UI template preserves its literal user-supplied name');
  byId('workflow-template-cancel-btn').click();
  const templateId = core.state.workflowTemplates[0].id;
  check(byId('workflow-list').textContent.includes('0 ejecuciones'), 'Template sidebar plural summaries translate');
  check(byId('workflow-execution-title').textContent === 'My template <&>', 'User template names are not translated');
  const projectId = 'i18n-project';
  core.state.projects.push({ id: projectId, name: 'My project <&>' });
  workflows.openProcessDialog({ templateId, projectId });
  const processName = change('workflow-process-name', 'Mi proceso <&>');
  processName.focus(); processName.setSelectionRange(2, 6);
  const projectOption = byId('workflow-process-project').selectedOptions[0];
  i18n.setLocale('en');
  check(byId('workflow-process-dialog').open && byId('workflow-process-project').value === projectId && processName.value === 'Mi proceso <&>', 'An open process dialog preserves its selections and name');
  check(document.activeElement === processName && processName.selectionStart === 2 && processName.selectionEnd === 6 && projectOption === byId('workflow-process-project').selectedOptions[0], 'Process dialog focus and option identity survive translation');
  i18n.setLocale('es');
  byId('workflow-process-form').dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
  check(!byId('workflow-process-dialog').open && core.state.workflows.some(item => item.name === 'Mi proceso <&>' && item.projectId === projectId), 'Process creation works normally in Spanish');
  check(byId('workflow-list').textContent.includes('1 ejecución'), 'Workflow sidebar uses Spanish singular for one run');
  const saved = JSON.stringify(core.state.workflows);
  i18n.setLocale('en'); i18n.setLocale('es');
  check(JSON.stringify(core.state.workflows) === saved && byId('workflow-execution-title').textContent === 'My template <&>', 'Language changes never rewrite persisted workflow content or user titles');
  workflows.history.undo(); await settle();
  check(core.state.workflows.length === 0 && core.state.workflowTemplates.length === 1, 'Workflow undo still removes only the created process');
  workflows.history.redo(); await settle();
  check(core.state.workflows[0]?.name === 'Mi proceso <&>', 'Workflow redo restores the process and its user content');
  const { checkLocalizedExecution } = await import('./execution-checks.mjs');
  window.qaI18nExecution = await checkLocalizedExecution({ core, i18n, check });
}
